import { chromium } from 'playwright';

const BASE = 'http://localhost:3021';
const SHOTS = '/tmp/claude-0/-/a847f019-50a6-4b60-bcba-1133f2a3ca8a/scratchpad/shots';

const PAGES = [
  { path: '/dashboard/domains', name: 'domains' },
  { path: '/dashboard/ssl', name: 'ssl' },
  { path: '/dashboard/email', name: 'email' },
  { path: '/dashboard/mail', name: 'mail' },
  { path: '/dashboard/migrate', name: 'migrate' },
  { path: '/dashboard/tools', name: 'tools' },
  { path: '/dashboard/directory', name: 'directory' },
  { path: '/dashboard/build', name: 'build' },
  { path: '/dashboard/claude-code', name: 'claude-code' },
];

const VIEWPORTS = [
  { width: 1600, height: 1000, tag: '1600' },
  { width: 1920, height: 1080, tag: '1920' },
];

async function login(page) {
  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' });
  // try to find email/password fields
  const emailSel = 'input[type="email"], input[name="email"]';
  const passSel = 'input[type="password"], input[name="password"]';
  await page.waitForSelector(emailSel, { timeout: 10000 });
  await page.fill(emailSel, 'admin@nxeon.local');
  await page.fill(passSel, 'iCwEt7PDdo0ne3YM');
  await page.click('button[type="submit"]');
  await page.waitForURL(/dashboard/, { timeout: 15000 }).catch(() => {});
  await page.waitForTimeout(1000);
}

(async () => {
  const browser = await chromium.launch();
  const results: any[] = [];

  for (const theme of ['dark', 'light']) {
    for (const vp of VIEWPORTS) {
      const context = await browser.newContext({ viewport: { width: vp.width, height: vp.height } });
      await context.addInitScript((t) => {
        try { window.localStorage.setItem('nx-theme', t); } catch {}
      }, theme);
      const page = await context.newPage();

      const consoleErrors: Record<string, string[]> = {};
      page.on('console', (msg) => {
        if (msg.type() === 'error' || msg.type() === 'warning') {
          const url = page.url();
          if (!consoleErrors[url]) consoleErrors[url] = [];
          consoleErrors[url].push(`[${msg.type()}] ${msg.text()}`);
        }
      });
      page.on('pageerror', (err) => {
        const url = page.url();
        if (!consoleErrors[url]) consoleErrors[url] = [];
        consoleErrors[url].push(`[pageerror] ${err.message}`);
      });

      await login(page);

      for (const p of PAGES) {
        consoleErrors[BASE + p.path] = [];
        try {
          await page.goto(`${BASE}${p.path}`, { waitUntil: 'networkidle', timeout: 20000 });
        } catch (e) {
          results.push({ theme, vp: vp.tag, page: p.name, error: `goto failed: ${e}` });
          continue;
        }
        await page.waitForTimeout(1500);
        const shotPath = `${SHOTS}/${p.name}_${theme}_${vp.tag}.png`;
        await page.screenshot({ path: shotPath, fullPage: true }).catch((e) => {
          results.push({ theme, vp: vp.tag, page: p.name, error: `screenshot failed: ${e}` });
        });
        const html = await page.content();
        results.push({
          theme,
          vp: vp.tag,
          page: p.name,
          url: page.url(),
          shot: shotPath,
          bodyLen: html.length,
          errors: consoleErrors[page.url()] || [],
        });
      }

      await context.close();
    }
  }

  await browser.close();
  console.log(JSON.stringify(results, null, 2));
})();

