import { chromium } from 'playwright';

const BASE = 'http://localhost:3021';

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ viewport: { width: 1600, height: 1000 } });
  await context.addInitScript(() => { try { window.localStorage.setItem('nx-theme', 'light'); } catch {} });
  const page = await context.newPage();

  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' });
  await page.fill('input[type="email"]', 'admin@nxeon.local');
  await page.fill('input[type="password"]', 'iCwEt7PDdo0ne3YM');
  await page.click('form button:has-text("Sign in")');
  await page.waitForURL(/dashboard/, { timeout: 15000 }).catch(() => {});
  await page.waitForTimeout(1000);
  await page.goto(`${BASE}/dashboard/domains`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1500);

  const info = await page.evaluate(() => {
    const btns = Array.from(document.querySelectorAll('button')).filter(b => b.textContent?.trim() === 'Opt out');
    if (btns.length === 0) return { found: false };
    const b = btns[0] as HTMLElement;
    const cs = getComputedStyle(b);
    // find nearest ancestor with data-theme or class
    let anc = b.parentElement;
    const chain: string[] = [];
    while (anc) {
      chain.push(anc.tagName + '.' + anc.className + (anc.getAttribute('data-theme') ? '[data-theme=' + anc.getAttribute('data-theme') + ']' : ''));
      anc = anc.parentElement;
    }
    return {
      found: true,
      className: b.className,
      color: cs.color,
      backgroundColor: cs.backgroundColor,
      borderColor: cs.borderColor,
      htmlDataTheme: document.documentElement.getAttribute('data-theme'),
      chain: chain.slice(0, 6),
    };
  });
  console.log(JSON.stringify(info, null, 2));

  await browser.close();
})();

