  await page.waitForTimeout(1000);

  const info = await page.evaluate(() => {
    const els = Array.from(document.querySelectorAll('p,span,div')).filter(e => e.textContent?.trim() === '$1.59/mo' || /\/mo$/.test(e.textContent?.trim() || '') && e.children.length === 0);
    const results = [];
    for (const el of els.slice(0, 5)) {
      const e = el as HTMLElement;
      const cs = getComputedStyle(e);
      let bgEl: HTMLElement | null = e;
      let bg = 'rgba(0,0,0,0)';
      while (bgEl) {
        const c = getComputedStyle(bgEl).backgroundColor;
        if (c && c !== 'rgba(0, 0, 0, 0)') { bg = c; break; }
        bgEl = bgEl.parentElement;
      }
      results.push({ text: e.textContent, className: e.className, color: cs.color, effectiveBg: bg });
    }
    return results;
  });
  console.log(JSON.stringify(info, null, 2));

  await browser.close();
})();

